<template>
<AdminLayout><div class="container mx-auto px-3 py-6 md:px-6"><div class="mb-6 flex flex-wrap items-center justify-between gap-3"><div><h1 class="text-3xl font-semibold text-slate-800">Vehículos</h1><p class="text-sm text-slate-500">Vehículos habilitados para reparto propio</p></div><button class="min-h-11 rounded-lg bg-blue-600 px-4 font-semibold text-white" @click="open()"><i class="pi pi-plus mr-2"/>Nuevo vehículo</button></div><div class="mb-4 flex gap-3"><input v-model="search" class="min-h-11 w-full rounded-lg border p-3 md:w-96" placeholder="Buscar por código, placa o marca" @input="load"><select v-model="type" class="min-h-11 rounded-lg border px-3" @change="load"><option value="">Todos los tipos</option><option v-for="value in types" :key="value" :value="value">{{value}}</option></select></div><div v-if="loading" class="rounded-xl bg-white p-10 text-center">Cargando vehículos…</div><div v-else class="grid gap-4 lg:grid-cols-2"><article v-for="item in items" :key="item.id" class="rounded-xl border bg-white p-5 shadow-sm"><div class="flex justify-between gap-3"><div><span class="font-mono text-xs text-slate-500">{{item.code}}</span><h2 class="text-lg font-bold">{{item.plate_number||'Sin placa'}} · {{item.vehicle_type}}</h2><p class="text-sm text-slate-600">{{[item.brand,item.model].filter(Boolean).join(' ')||'Descripción pendiente'}}</p></div><span class="rounded-full px-2 py-1 text-xs font-semibold" :class="item.is_active?(item.is_available?'bg-emerald-100 text-emerald-700':'bg-amber-100 text-amber-700'):'bg-slate-200 text-slate-600'">{{item.is_active?(item.is_available?'Disponible':'No disponible'):'Inactivo'}}</span></div><div v-if="warning(item)" class="mt-3 rounded bg-red-50 p-3 text-sm text-red-800">{{warning(item)}}</div><div class="mt-4 grid grid-cols-2 gap-2 text-sm"><div class="rounded bg-slate-50 p-3">{{item.active_deliveries_count||0}} entrega activa</div><div class="rounded bg-slate-50 p-3">{{item.deliveries_count||0}} entregas totales</div></div><div class="mt-4 flex justify-end gap-2 border-t pt-3"><button class="rounded px-3 py-2 text-blue-700" @click="open(item)"><i class="pi pi-pencil"/></button><button class="rounded px-3 py-2 text-sm text-amber-700" :disabled="!item.is_active" @click="toggleAvailability(item)">{{item.is_available?'No disponible':'Disponible'}}</button><button class="rounded px-3 py-2 text-sm text-red-700" @click="toggleActive(item)">{{item.is_active?'Desactivar':'Activar'}}</button></div></article><div v-if="!items.length" class="rounded-xl bg-white p-10 text-center text-slate-500 lg:col-span-2">No hay vehículos registrados.</div></div><div v-if="modal" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/60 p-3"><form class="max-h-[94vh] w-full max-w-2xl overflow-y-auto rounded-xl bg-white p-6" @submit.prevent="save"><div class="mb-5 flex justify-between"><h2 class="text-xl font-bold">{{form.id?'Editar':'Nuevo'}} vehículo</h2><button type="button" class="text-2xl" @click="modal=false">&times;</button></div><div class="grid gap-3 md:grid-cols-2"><label>Código<input v-model="form.code" required class="field"></label><label>Placa<input v-model="form.plate_number" class="field" placeholder="Opcional para bicicletas"></label><label>Tipo<select v-model="form.vehicle_type" required class="field"><option v-for="value in types" :key="value" :value="value">{{value}}</option></select></label><label>Propiedad<select v-model="form.ownership_type" required class="field"><option value="company">Empresa</option><option value="driver">Repartidor</option><option value="third_party">Tercero</option></select></label><label>Marca<input v-model="form.brand" class="field"></label><label>Modelo<input v-model="form.model" class="field"></label><label>Año<input v-model="form.year" type="number" class="field"></label><label>Color<input v-model="form.color" class="field"></label><label>SOAT vence<input v-model="form.soat_expires_at" type="date" class="field"></label><label>Revisión técnica vence<input v-model="form.technical_inspection_expires_at" type="date" class="field"></label><label class="md:col-span-2">Notas<textarea v-model="form.notes" class="field"/></label><label class="flex gap-2"><input v-model="form.is_active" type="checkbox"> Activo</label><label class="flex gap-2"><input v-model="form.is_available" type="checkbox"> Disponible</label></div><div class="mt-5 flex justify-end gap-3"><button type="button" class="rounded bg-slate-100 px-4 py-2" @click="modal=false">Cancelar</button><button class="rounded bg-blue-600 px-4 py-2 font-semibold text-white" :disabled="saving">Guardar</button></div></form></div></div></AdminLayout>
</template>
<script setup>
import {onMounted,ref} from 'vue';import AdminLayout from '@/layouts/AdminLayout.vue';import api from '@/api';import {useToast} from 'primevue/usetoast';
const toast=useToast(),items=ref([]),search=ref(''),type=ref(''),loading=ref(false),modal=ref(false),saving=ref(false),form=ref({});let timer;const types=['motorcycle','car','van','truck','bicycle','other'];const empty=()=>({code:'',plate_number:'',vehicle_type:'motorcycle',ownership_type:'company',brand:'',model:'',year:'',color:'',soat_expires_at:'',technical_inspection_expires_at:'',notes:'',is_active:true,is_available:true});const message=e=>e.response?.data?.message||Object.values(e.response?.data?.errors||{})[0]?.[0]||'No se pudo completar la operación.';const warning=i=>{const today=new Date(),soon=new Date();soon.setDate(today.getDate()+30);const dates=[['SOAT',i.soat_expires_at],['Revisión técnica',i.technical_inspection_expires_at]].filter(([,v])=>v).map(([label,v])=>[label,new Date(v)]);const expired=dates.find(([,v])=>v<today);if(expired)return `${expired[0]} vencido`;const near=dates.find(([,v])=>v<=soon);return near?`${near[0]} próximo a vencer`:''};function load(){clearTimeout(timer);timer=setTimeout(async()=>{loading.value=true;try{items.value=(await api.get('/admin/delivery-vehicles',{params:{search:search.value,type:type.value}})).data.data}catch(e){toast.add({severity:'error',summary:'Error',detail:message(e),life:4000})}finally{loading.value=false}},150)}function open(item=null){form.value=item?{...item}:empty();modal.value=true}async function save(){saving.value=true;try{form.value.id?await api.put(`/admin/delivery-vehicles/${form.value.id}`,form.value):await api.post('/admin/delivery-vehicles',form.value);modal.value=false;load()}catch(e){toast.add({severity:'error',summary:'No se pudo guardar',detail:message(e),life:5000})}finally{saving.value=false}}async function toggleActive(item){try{await api.patch(`/admin/delivery-vehicles/${item.id}/status`,{is_active:!item.is_active});load()}catch(e){toast.add({severity:'warn',summary:'Operación rechazada',detail:message(e),life:4000})}}async function toggleAvailability(item){try{await api.patch(`/admin/delivery-vehicles/${item.id}/availability`,{is_available:!item.is_available});load()}catch(e){toast.add({severity:'warn',summary:'Operación rechazada',detail:message(e),life:4000})}}onMounted(load);
</script><style scoped>.field{@apply mt-1 block min-h-11 w-full rounded-lg border border-slate-300 p-2}</style>
